#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <string>

using namespace std;

char matrixA[12][12], matrixB[12][12];
int sizeN, maxTime;
bool dpVisited[70][12][12][12][12];
bool canReach[12][12][12][12];
int timeGrid[12][12];

void propagateDP(int tStep, int x, int y, int xRef, int yRef) {
    if (maxTime >= 70 || x < 0 || x >= sizeN || y < 0 || y >= sizeN)
        return;
    if (matrixA[x][y] < '0' || matrixA[x][y] > '9')
        return;
    if (tStep > maxTime + 1)
        return;
    if (dpVisited[tStep][x][y][xRef][yRef])
        return;
    if (timeGrid[x][y] != 0 && tStep > timeGrid[x][y])
        return;
    if (timeGrid[x][y] == tStep && (matrixB[x][y] > '9' || matrixB[x][y] <= '0'))
        return;
    dpVisited[tStep][x][y][xRef][yRef] = true;

    if (tStep < timeGrid[x][y]) {
        propagateDP(tStep + 1, x, y, xRef, yRef);
        propagateDP(tStep + 1, x + 1, y, xRef, yRef);
        propagateDP(tStep + 1, x - 1, y, xRef, yRef);
        propagateDP(tStep + 1, x, y + 1, xRef, yRef);
        propagateDP(tStep + 1, x, y - 1, xRef, yRef);
    }
}

int main() {
    int n, t;
    cin >> n >> t;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> matrixA[i][j];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> matrixB[i][j];

    vector<vector<int>> graph;
    vector<int> E(210, 0), H(210, 0);
    int C[210][210] = {0};
    int pN[11][11] = {0};

    queue<pair<int, int>> q;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            timeGrid[i][j] = -1;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (matrixA[i][j] == 'Z') {
                timeGrid[i][j] = 0;
                q.push({i, j});
            }

    int di[] = {-1, 0, 1, 0};
    int dj[] = {0, -1, 0, 1};

    while (!q.empty()) {
        auto p = q.front(); q.pop();
        if (timeGrid[p.first][p.second] >= t) continue;
        for (int d = 0; d < 4; d++) {
            int ni = p.first + di[d], nj = p.second + dj[d];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n && matrixA[ni][nj] >= '0' && matrixA[ni][nj] <= '9' && timeGrid[ni][nj] == -1) {
                timeGrid[ni][nj] = timeGrid[p.first][p.second] + 1;
                q.push({ni, nj});
            }
        }
    }

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (timeGrid[i][j] == -1)
                timeGrid[i][j] = t;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (matrixA[i][j] >= '0' && matrixA[i][j] <= '9')
                propagateDP(0, i, j, i, j);

    vector<int> startNodes;
    graph.push_back(startNodes);

    for (int i1 = 0; i1 < n; i1++)
        for (int j1 = 0; j1 < n; j1++)
            for (int i2 = 0; i2 < n; i2++)
                for (int j2 = 0; j2 < n; j2++)
                    for (int nt = 0; nt <= t; nt++)
                        canReach[i1][j1][i2][j2] |= dpVisited[nt][i1][j1][i2][j2];

    for (int i1 = 0; i1 < n; i1++)
        for (int j1 = 0; j1 < n; j1++)
            if (matrixA[i1][j1] > '0' && matrixA[i1][j1] <= '9') {
                int k = graph.size();
                vector<int> g;
                graph.push_back(g);
                E[k] = matrixA[i1][j1] - '0';

                for (int i2 = 0; i2 < n; i2++)
                    for (int j2 = 0; j2 < n; j2++)
                        if (matrixB[i2][j2] > '0' && matrixB[i2][j2] <= '9')
                            if (canReach[i2][j2][i1][j1]) {
                                int _k;
                                if (pN[i2][j2] == 0) {
                                    vector<int> _g;
                                    _k = graph.size();
                                    graph.push_back(_g);
                                    pN[i2][j2] = _k;
                                } else {
                                    _k = pN[i2][j2];
                                }
                                graph[k].push_back(_k);
                                graph[_k].push_back(k);
                                C[k][_k] = 10000;
                                C[_k][k] = 0;
                            }
            }

    for (int i2 = 0; i2 < n; i2++)
        for (int j2 = 0; j2 < n; j2++)
            if (matrixB[i2][j2] > '0' && matrixB[i2][j2] <= '9' && pN[i2][j2] > 0) {
                int _k = pN[i2][j2];
                graph[_k].push_back(0);
                C[_k][0] = matrixB[i2][j2] - '0';
                C[0][_k] = 0;
            }

    while (true) {
        bool done = true;
        for (int i = 1; i < (int)graph.size(); i++) {
            while (E[i] > 0) {
                bool progressFlag = true;
                int minH = 10000;
                for (int neighbor : graph[i]) {
                    if (C[i][neighbor] - E[i] > 0 && H[i] == H[neighbor] + 1) {
                        int deltaFlow = min(C[i][neighbor] - E[i], E[i]);
                        F[i][neighbor] += deltaFlow;
                        F[neighbor][i] -= deltaFlow;
                        E[i] -= deltaFlow;
                        E[neighbor] += deltaFlow;
                        progressFlag = false;
                        done = false;
                        if (E[i] == 0) break;
                    }
                    minH = min(minH, H[neighbor]);
                }
                if (H[i] != minH + 1 && minH != 10000)
                    H[i] = minH + 1;
                if (progressFlag) break;
            }
        }
        if (done) break;
    }

    cout << E[0] << endl;
    return 0;
}
